verify_sources();g<-priv('governed_pivot.rds');o<-clean(g);f<-priv('official_F4_clean.rds');i<-match(f$id_per,o$id_per)
d<-data.frame(id_per=f$id_per,upm=as.character(f$upm),estrato=as.character(f$estrato),fexp=as.numeric(f$fexp),IN_OWOB_PIVOT=!is.na(i),edadanios=o$edadanios[i],sexo=g$OWOBNEW_SEX[i],area=g$OWOBNEW_AREA[i],etnia=g$OWOBNEW_ETHNICITY[i],F4_sex=f$sexo,F4_area=f$area,F4_region=f$region,F4_age=f$f4_s1_6)
for(v in names(g)[startsWith(names(g),'OWOBNEW_')])d[[v]]<-g[[v]][i]
stopifnot(nrow(d)==23621,sum(d$IN_OWOB_PIVOT)==19750,!anyDuplicated(d$id_per),all(is.na(d$OWOBNEW_OHRP6[!d$IN_OWOB_PIVOT])))
np<-tapply(d$upm,d$estrato,function(x)length(unique(x)));ok<-all(is.finite(d$fexp)&d$fexp>0)&!anyNA(d$upm)&!anyNA(d$estrato)&all(np>1)&(sum(np)-length(np)>0)
wc(data.frame(check=c('full_frame_rows','positive_finite_weights','unique_nested_PSU','strata','full_singleton_strata','design_df','pivot_members','outside_pivot_NA_analytic'),value=c(nrow(d),sum(is.finite(d$fexp)&d$fexp>0),sum(np),length(np),sum(np==1),sum(np)-length(np),sum(d$IN_OWOB_PIVOT),sum(is.na(d$OWOBNEW_OHRP6[!d$IN_OWOB_PIVOT]))),status=if(ok)'PASS'else'BLOCKED'),'DESIGN_PSU_STRATA_DF_QA.csv')
wc(data.frame(PSU_per_stratum=as.numeric(names(table(np))),N_strata=as.integer(table(np))),'DESIGN_PSU_PER_STRATUM_DISTRIBUTION.csv')
wc(data.frame(scope=c('FULL_F4','PIVOT','OUTSIDE_PIVOT'),N=c(nrow(d),sum(d$IN_OWOB_PIVOT),sum(!d$IN_OWOB_PIVOT)),weight_sum=c(sum(d$fexp),sum(d$fexp[d$IN_OWOB_PIVOT]),sum(d$fexp[!d$IN_OWOB_PIVOT])),weight_min=c(min(d$fexp),min(d$fexp[d$IN_OWOB_PIVOT]),min(d$fexp[!d$IN_OWOB_PIVOT])),weight_max=c(max(d$fexp),max(d$fexp[d$IN_OWOB_PIVOT]),max(d$fexp[!d$IN_OWOB_PIVOT])),weight_CV=c(sd(d$fexp)/mean(d$fexp),sd(d$fexp[d$IN_OWOB_PIVOT])/mean(d$fexp[d$IN_OWOB_PIVOT]),sd(d$fexp[!d$IN_OWOB_PIVOT])/mean(d$fexp[!d$IN_OWOB_PIVOT]))),'WEIGHT_DIAGNOSTICS.csv')
if(ok){design<-with_policy('fail',FALSE,survey::svydesign(ids=~upm,strata=~estrato,weights=~fexp,data=d,nest=TRUE));stopifnot(survey::degf(design)==sum(np)-length(np));savepriv(design,'full_F4_design.rds')}else newblock('BLOCKED_DESIGN_ESTIMABILITY','survey estimation','Full-frame weights or PSU/strata failed','Resolve source design; no inferred certainty/FPC')
savepriv(d,'analysis_frame.rds')
sel<-list();kk<-0;for(v in c('F4_sex','F4_area','F4_region','F4_age'))for(scope in c('FULL_F4','PIVOT','OUTSIDE_PIVOT')){ix<-if(scope=='FULL_F4')rep(TRUE,nrow(d))else if(scope=='PIVOT')d$IN_OWOB_PIVOT else !d$IN_OWOB_PIVOT;val<-ifelse(is.na(d[[v]]),'MISSING',as.character(d[[v]]));for(cat in sort(unique(val))){ii<-ix&val==cat;kk<-kk+1L;sel[[kk]]<-data.frame(variable=v,category=cat,scope=scope,N=sum(ii),denominator=sum(ix),proportion_unweighted=sum(ii)/sum(ix),weight_sum=sum(d$fexp[ii]),proportion_weighted=sum(d$fexp[ii])/sum(d$fexp[ix]))}}
wc(do.call(rbind,sel),'F4_VS_PIVOT_SELECTION_DIAGNOSTICS.csv')
writeLines(c('# Diseño muestral OWOB-01D','', 'El diseño se declara sobre23.621 registros F4, antes de restringir a pivote, dominio o casos completos. Se usa svydesign(ids=~upm,strata=~estrato,weights=~fexp,nest=TRUE). Sin FPC inventado ni modificación de pesos originales. Fuera del pivote los outcomes y constructos analíticos son NA.','',paste('Marco verificado:',sum(np),'UPM anidadas,',length(np),'estratos,',sum(np==1),'singleton completos,',sum(np)-length(np),'grados de libertad.'),'', 'Política primaria fail/FALSE: corresponde al marco F4 validado y preserva la linealización por dominio. La regla provisional adjust/TRUE del encargo se cotejó con LONELY_PSU_DECISION.md y SURVEY_FRAME_VALIDATION.md. La fase L2 de otro análisis usó adjust/TRUE también para un RAW declarado directamente, una situación distinta. Sensibilidades fijas adjust/TRUE y average/TRUE se aplican a cada principal sin cambiar muestra/fórmula.','', 'Cada svyglm usa subset del diseño completo. Cada glm usa exactamente las filas y orden del mismo objeto de dominio. Los DF residuales para Wald-t son los devueltos por svyglm, no n-p; se reportan separadamente del degf del diseño de dominio. Una UPM contribuyente en un dominio no implica singleton del diseño completo.','', 'La muestra pivote no tiene selección histórica documentada; el diseño F4 no subsana por sí mismo selección diferencial. Pesos totales se reportan como masa poblacional de referencia y nunca como número observado. Las prevalencias se interpretan para el dominio analítico bajo estos supuestos, no como estimaciones nacionales certificadas.'),'docs/OWOB01D_SURVEY_DESIGN_METHOD.md')
cat('Gate D:',if(ok)'PASS'else'BLOCKED','; full F4',nrow(d),';PSU',sum(np),';strata',length(np),'\n')
